"(immediate = false) => {
        if (!this.disabled) {
            if (this.showTimeout !== null) {
                clearTimeout(this.showTimeout);
            }

            const show = async () => {
                await this.updatePosition();
                this.active = true;
                this.showTimeout = null;
                this.wasHiddenByVisibility = false;
                this._onShowEvent(true);
            };

            if (immediate) {
                show();
            } else {
                this.showTimeout = window.setTimeout(show, 300);
            }
        }
    }"

